function [c, n, E1, E2] = bisection(f, a, b, tol1, tol2, MaxIt)% Simplified fixed point algorithm to find a root of f(x) within [a,b].%% INPUTS:% f     = function handle for the target function% a, b  = interval endpoints where the root is sought% tol1    = tolerance on the function value at c% tol2    = tolerance on the distance from c to the actual zero% MaxIt = maximum number of iterations%% OUTPUTS:% c  = computed zero location% n  = final iteration count% E1 = |f(c)|% E2 = maximum possible distance from c to the actual zero% Checks if initial conditions are metif nargin < 3    error('A function and an interval are required.')endif f(a)*f(b) > 0    error('f(a)f(b) > 0: The interval may not contain a root.')end% Default values for optional inputsif nargin < 4    tol1 = 1e-4;endif nargin < 5    tol2 = 1e-4;endif nargin < 6    MaxIt = 100;end% Initialize variablesn = 1;c = (a + b) / 2;E2 = b - a;E1(1)=abs(f(c));% Main iteration loopwhile E1(n) > tol1 && E2 > tol2 && n < MaxIt    n = n + 1;    if f(a) * f(c) < 0        b = c;    else        a = c;    end    c = (a + b) / 2;    E1(n) = abs(f(c));    E2 = (b - a) / 2;end% Display warnings if necessaryif E1(n) > tol1    warning('Desired precision not reached. Final error: %g', E1(n));endif n >= MaxIt    warning('Maximum number of iterations reached.');endclffigure(1)subplot(1,2,1)plot(E1(2:n), 'b-o')title('Error vs. Iteraciones')xlabel('Nmero de Iteraciones')ylabel('Error')grid onsubplot(1,2,2)plot(log(E1(2:n)), 'b-o')title('log(Error) vs. Iteraciones')xlabel('Nmero de Iteraciones')ylabel('log(Error)')grid onend